    html: "<label class=\"radio-button\">\n  <input type=\"radio\" name=\"example-radio\" value=\"option1\">\n  <span class=\"radio\"></span>\n  Option 1\n</label>\n\n<label class=\"radio-button\">\n  <input type=\"radio\" name=\"example-radio\" value=\"option2\">\n  <span class=\"radio\"></span>\n  Option 2\n</label>",
