    html: "<div class=\"btn-group\">\n  <button class=\"btn left\" type=\"button\">Left</button>\n  <button class=\"btn middle\" type=\"button\">Middle</button>\n  <button class=\"btn right\" type=\"button\">Right</button>\n</div>",
    css: "/* From Uiverse.io by elijahgummer  - Tags: simple, animation, jelly, shadow, modern, radio, stretch, alignment */\n.btn {\n  font: inherit;\n  background-color: #f0f0f0;\n  border: 0;\n  color: #242424;\n  font-size: 1.15rem;\n  padding: 0.375em 1em;\n  text-shadow: 0 0.0625em 0 #fff;\n  box-shadow: inset 0 0.0625em 0 0 #f4f4f4, 0 0.0625em 0 0 #efefef,\n    0 0.125em 0 0 #ececec, 0 0.25em 0 0 #e0e0e0, 0 0.3125em 0 0 #dedede,\n    0 0.375em 0 0 #dcdcdc, 0 0.425em 0 0 #cacaca, 0 0.425em 0.5em 0 #cecece;\n  transition: 0.23s ease;\n  cursor: pointer;\n  font-weight: bold;\n  margin: -1px;\n}\n.middle {\n  border-radius: 0px;\n}\n.right {\n  border-top-right-radius: 0.5em;\n  border-bottom-right-radius: 0.5em;\n}\n.left {\n  border-top-left-radius: 0.5em;\n  border-bottom-left-radius: 0.5em;\n}\n.btn:active {\n  translate: 0 0.225em;\n  box-shadow: inset 0 0.03em 0 0 #f4f4f4, 0 0.03em 0 0 #efefef,\n    0 0.0625em 0 0 #ececec, 0 0.125em 0 0 #e0e0e0, 0 0.125em 0 0 #dedede,\n    0 0.2em 0 0 #dcdcdc, 0 0.225em 0 0 #cacaca, 0 0.225em 0.375em 0 #cecece;\n  letter-spacing: 0.1em;\n  color: skyblue;\n}\n.btn:focus {\n  color: skyblue;\n}",
